module tb_TopModule;
    logic clk;
    logic areset;
    logic x;
    logic z;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        x = 0;
        #12;
        areset = 0;
        #10;

        // Sequence: test 2's complementer behavior on input bitstream (e.g., 4'b1010 -> LSB first: x=0,1,0,1)
        // Let's trace manual expected outputs for stream:
        // A, x=0 -> z=0, state A
        // x=1 -> z=1, state B
        // x=0 -> z=1, state B
        // x=1 -> z=0, state B

        // Reset check
        if (z !== 0) begin
            $display("SELFTEST FAIL: Reset output incorrect");
            $finish;
        end

        // Input x = 0 in state A -> z = 0, state A
        x = 0; @(posedge clk); #1;
        if (z !== 0) begin $display("SELFTEST FAIL at step 1"); $finish; end

        // Input x = 1 in state A -> z = 1, state B
        x = 1; @(posedge clk); #1;
        if (z !== 1) begin $display("SELFTEST FAIL at step 2"); $finish; end

        // Input x = 0 in state B -> z = 1, state B
        x = 0; @(posedge clk); #1;
        if (z !== 1) begin $display("SELFTEST FAIL at step 3"); $finish; end

        // Input x = 1 in state B -> z = 0, state B
        x = 1; @(posedge clk); #1;
        if (z !== 0) begin $display("SELFTEST FAIL at step 4"); $finish; end

        // Test asynchronous reset during operation
        areset = 1; #3;
        if (z !== 0) begin $display("SELFTEST FAIL: Async reset output"); $finish; end
        areset = 0; #7;

        // Check back in state A with x=1 -> z=1, state B
        x = 1; @(posedge clk); #1;
        if (z !== 1) begin $display("SELFTEST FAIL at step 5"); $finish; end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

